function GoodNodeMB:InitStub()
    if not self.CatBall then
        local catBall = self.CatBallStub.transform:Find('CatBall')
        if isNotNull(catBall) then
            GameObject.Destroy(catBall.gameObject)
        end
    end

    if not self.EquipAndCore then
        local equipAndCore = self.EquipAndCoreStub.transform:Find('EquipAndCore')
        if isNotNull(equipAndCore) then
            GameObject.Destroy(equipAndCore.gameObject)
        end
    end

    if not self.CommonPlayerHeadNode then
        local commonPlayerHeadNode = self.CommonPlayerHeadNodeStub.transform:Find('CommonPlayerHeadNode')
        if isNotNull(commonPlayerHeadNode) then
            GameObject.Destroy(commonPlayerHeadNode.gameObject)
        end
    end
end


