---Reload
---二次重置刷新节点，特殊需要时调用
---@param params GoodNodeMB.InputData
function GoodNodeMB:Reload(params)
    self:SetRoleGradeAndCareerState(false)
    
    UICommonUtils.PlayButtonAnimByName(self.Container, "UI_Common_ButtonIdle")

    if self.EquipAndCore then
        KTool.SetActive(self.EquipAndCore.gameObject, false)
    end 

    CfUtils.SetActive(self.LvOrNoTxt, false)

    if self.CommonPlayerHeadNode then
        KTool.SetActive(self.CommonPlayerHeadNode.gameObject, false)
    end

    if self.CatBall then
        KTool.SetActive(self.CatBall.gameObject, false)
    end
    KTool.SetActive(self.Icon.gameObject, true)
    CfUtils.SetActive(self.IconCardHead, false)
    
    if self.RoleLvGroup then
        KTool.SetActive(self.RoleLvGroup.gameObject, false)    
    end
    
    if self.ImgShelter then
        KTool.SetActive(self.ImgShelter.gameObject, false)    
    end

    if not isNull(params) and isTable(params) then
        self.params = params
    end

    if not isSet(self.params, "goodsId") then
        return
    end
    local goodsId = checkNumber(self.params.goodsId)
    if goodsId <= 0 then
        return
    end

    local isShowNo = checkBool(self.params.isShowNo)
    local isShowNoX = checkBool(self.params.isShowNoX)
    if isShowNoX then
        isShowNo = true
        self.params.text = string.fmt('x%1', GoodsUtils.GetThingNo(goodsId))
    end

    local id = 0
    if isSet(self.params, "dojo") then
        id = checkNumber(self.params.dojo.id)
    elseif isSet(self.params, "id") then
        id = checkNumber(self.params.id)
    end

    local idAreaType
    if isSet(self.params, "idAreaType") then
        idAreaType = checkNumber(self.params.idAreaType)
    end

    local rewardSource = Constants.RewardSourceType.None
    if isSet(self.params, "superScript") then
        rewardSource = checkNumber(self.params.superScript)
    end

    --初始化的时候把可使用道具需要的属性置空
    -- self:__ClearUsableGoodStatus()
    -- if self.BGAnim then
    --     KTool.SetActive(self.BGAnim.gameObject, false)
    -- end
    KTool.SetActive(self.countDownBg, false)
    KTool.SetActive(self.Container:Find("Imgoccupation"), false)
    
    local idType = GoodsUtils.GetIdType(goodsId, idAreaType)

    local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId, idAreaType)

    if isNull(vo) then
        printError("id %s 找不到道具信息 有可能是投产了 然后表被关了",goodsId)
        return
    end

    if idType == Constants.IDType.Equipment then
        self.goodType = GoodType.Equip
        --tarot
        self:__FreshEquipInfo(id, goodsId)
    --定制装备
    elseif idType == Constants.IDType.GoodsCommission then
        self.goodType = GoodType.Equip
        if vo then
            self:__FreshEquipInfo(id, goodsId, true)
        end
    -- elseif idType == Constants.IDType.EquipmentCore then
    --     self.goodType = GoodType.EquipCore
    --     --tarot
    --     self:__FreshEquipCoreInfo(id, goodsId)
        --可使用道具部分
    --elseif idType == Constants.IDType.GoodsUsable then
    --    self.EventUsableGoodsTimeCountDown = Events.AddListener(Constants.EventNames.UIEventUsableGoodsTimeCountDown, Bind(self, self.OnUsableGoodsTimeCountDown))
    --    self.goodsId = goodsId
    --    self.id = id
    --    self:__FreshCommonGoodInfo(goodsId, isShowNo, self.params.text, idType, idAreaType)
    --    self:__FreshUsableGoodTimeInfo(goodsId, id, self.params.text, idAreaType)
    --    --迷宫部分特殊处理
    elseif idType == Constants.IDType.MazeItem or idType == Constants.IDType.Relics or idType == Constants.IDType.Curses then
        self.goodType = GoodType.Common
        local numText = nil
        if checkNumber(params.text) > 1 then
            numText = params.text
        end
        --tarot
        self:__FreshCommonGoodInfo(goodsId, true, numText, idType, idAreaType)
        self:__FreshMazeGood(goodsId, idType)
    elseif idType == Constants.IDType.CardSkin or idType == Constants.IDType.CharacterCard or idType == Constants.IDType.RoleCardCustomize or idType == Constants.IDType.PatrolMazeAssist then
        self.goodType = GoodType.Common
        KTool.SetActive(self.Icon.gameObject, true)
        -- if self.EquipAndCore then
        --     KTool.SetActive(self.EquipAndCore.gameObject, false)
        -- end
        self:__FreshCardBg(goodsId, idType)
        --普通道具才是id否则需要从玩家信息中获取
        self:__FreshCommonGoodInfo(goodsId, isShowNo, self.params.text, idType)

        self:SetRoleGradeAndCareerState(true, goodsId, id)

        local isRole = (idType == Constants.IDType.CharacterCard) or (idType == Constants.IDType.RoleCardCustomize) or (idType == Constants.IDType.PatrolMazeAssist)
        if self.RoleLvGroup then
            KTool.SetActive(self.RoleLvGroup.gameObject, isRole)
        end

        if idType == Constants.IDType.CharacterCard and self.RoleLvGroupText then
            local lv = self:GetCardLv(id)
            CfUtils.FillText(self.RoleLvGroupText, string.format("Lv.%s", lv))
        elseif idType == Constants.IDType.RoleCardCustomize and self.RoleLvGroupText then
            ---@type RoleCardCustomizeVo
            local cardVo = CardConfMgr:GetInstance():GetCustomizeCardVoById(goodsId)
            ---@type GetCardRobotAttributeVo
            local attributeVo = CardConfMgr:GetInstance():GetCardRobotAttributeVo(cardVo.effectId)
            local lv = attributeVo.cardLevel
            CfUtils.FillText(self.RoleLvGroupText, string.format("Lv.%s", lv))
        elseif idType == Constants.IDType.PatrolMazeAssist and self.RoleLvGroupText then
            local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
            local assistCardLevel = PatrolMazeUtils.GetParamValue(PatrolMazeUtils.ParamsId.INIT_CARD_LEVEL)
            CfUtils.FillText(self.RoleLvGroupText, string.format("Lv.%s", assistCardLevel))
        end
        CfUtils.SetActive(self.IconCardHead, true)
        CfUtils.SetActive(self.Icon, false)
    elseif idType ==Constants.IDType.GoodsHeadOrFrame and (checkNumber(vo.kind) == 1 or checkNumber(vo.kind) == 2 ) then
        self.goodType = GoodType.Common
        KTool.SetActive(self.Icon.gameObject, false)

        if not self.CommonPlayerHeadNode then
            self.CommonPlayerHeadNode = self.CommonPlayerHeadNodeStub:InstantiatePrefab("CommonPlayerHeadNode")
            self.CommonPlayerHeadNode.anchoredPosition = Vector2.New(0, 21.4)
            self.CommonPlayerHeadNode.localScale = Vector3.New(0.55, 0.55, 1)
            ---@type UnityEngine.UI.Image
            local commonPlayerHeadNodeImgMain = self.CommonPlayerHeadNode:Find('Root/ImgMain'):GetComponent(ImageType)
            commonPlayerHeadNodeImgMain.raycastTarget = false
        end 
        KTool.SetActive(self.CommonPlayerHeadNode.gameObject, true)

        -- if self.EquipAndCore then
        --     KTool.SetActive(self.EquipAndCore.gameObject, false)
        -- end 
        --普通道具才是id否则需要从玩家信息中获取
        self:__FreshCommonGoodInfo(goodsId, isShowNo, self.params.text, idType)
    elseif idType == Constants.IDType.GoodsCatBlindBox or idType == Constants.IDType.GoodsCatEggs then
        if isNull(self.CatBall) then
            self.CatBall = self.CatBallStub:InstantiatePrefab("CatBall", self)
        end 

        self:__FreshCatBall(goodsId,idType)
        self:__FreshCommonGoodInfo(goodsId, isShowNo, self.params.text, idType)
        self:SetRoleGradeAndCareerState(true, goodsId)
    elseif idType == Constants.IDType.BattleCardGameCard then
        self:__FreshBattleCardNode(goodsId)
        self:__FreshCommonGoodInfo(goodsId, isShowNo, self.params.text, idType)
    else

        self.goodType = GoodType.Common
        KTool.SetActive(self.Icon.gameObject, true)

        -- if self.EquipAndCore then
        --     KTool.SetActive(self.EquipAndCore.gameObject, false)
        -- end 
        --普通道具才是id否则需要从玩家信息中获取
        self:__FreshCommonGoodInfo(goodsId, isShowNo, self.params.text, idType)
    end

    if isShowNo then
        -- 如果不显示x1的文字，那么也不显示星星。即便需要显示星星，也是用外面tips组件的星星，不用这里的星星
        self:FillGoodsStarInfo(goodsId)     -- 这个里面会判断要不要显示星星
    else
        CfUtils.SetActive(self.GoodStar, false)
    end
    CfUtils.SetActive(self.ImgFreeGift, checkBool(self.params.isGift))
    self:FillScaleSize()
    self:FillSuperScript(rewardSource)
    if self.params and self.params.data and (checkNumber(self.params.data.specialEffect) == 1) then
        self:FillSpecialEffect()
    end
end

function GoodNodeMB:FillSpecialEffect()
    if isNotNull(self.__commonSpecialEffectGo) then
        CfUtils.SetActive(self.__commonSpecialEffectGo, true)
        return
    end
    local loader = CS.Engine.Modules.ResourceModule.LoadBundleSync('Effect/prefab/ui_prefab/UI_GoodNodeHighlight2.prefab', nil, true)
    if loader.IsSuccess then
        local parent = self.controller.transform
        self.__commonSpecialEffectGo = loader:Instantiate(parent.transform, false)
    end
    loader:Release()
end

function GoodNodeMB:FillScaleSize()
    local size = self.controller.gameObject.transform.localScale.x
    local textSize = 38
    if strict_number_equal(size, 1) then
        textSize = 38
    elseif strict_number_equal(size, 0.75) then
        textSize = 38
    elseif strict_number_equal(size, 0.65) then
        textSize = 42
    elseif strict_number_equal(size, 0.55) then
        textSize = 50
    elseif strict_number_equal(size, 0.5) then
        textSize = 58
    end

    self.LvOrNoTxt.fontSize = textSize
end

function GoodNodeMB:FillGoodsStarInfo(goodsId)
    if isNull(self.GoodStar) then
        return
    end
    if checkNumber(goodsId) <= 0 then
		return
	end

	local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
    if not goodsVo then
        return
    end
	local vo = CfUtils.GetCfVo(AutoIds.IdSetting4070, "GoodsShowTypeVo", goodsVo.showType)
	local isShowStar
	if vo then
		isShowStar = (checkNumber(vo.showStar) == 1)		
	end
    CfUtils.SetActive(self.GoodStar, isShowStar)

    if isShowStar then
        local num = checkNumber(goodsVo.quality)
        for i = 1, num do
            local go = self.GoodStar.transform:Find("go"..i)
            if isNull(go) then
                go = CfUtils.InstantiateGo(self.ImgStar, self.GoodStar)
                go.name = "go"..i
            end
            CfUtils.SetActive(go, true)
        end  

        if num + 1 < self.GoodStar.transform.childCount then
            for i = num + 1, self.GoodStar.transform.childCount do
                local go = self.GoodStar.transform:Find("go"..i)
                CfUtils.SetActive(go, false)
            end
        end
    end
end

---__FreshEquipInfo 私有方法
---刷新图型卡的样式
---@param id number 图型卡的数据库id
---@param goodsId number 图型卡的配表id
function GoodNodeMB:__FreshEquipInfo(id, goodsId, isCustom)
    if not self.EquipAndCore then 
        self.EquipAndCore = self.EquipAndCoreStub:InstantiatePrefab("EquipAndCore", self)
    end 

    KTool.SetActive(self.EquipAndCore.gameObject, true)
    KTool.SetActive(self.Equip.gameObject, true)

    --KTool.SetActive(self.EquipCore.gameObject, false)
    KTool.SetActive(self.Icon.gameObject, true)
    
    --- @type UnityEngine.RectTransform
    --KTool.SetActive(self.LvBg.gameObject, false)
    if self.ImgNumBg then
        KTool.SetActive(self.ImgNumBg.gameObject, false)
    end
    if self.EquipLvLabel then
        KTool.SetActive(self.EquipLvLabel.gameObject, true)
    end

    local equipRefId
    ---@type EquipDojo
    local equipDojo
    if isCustom then
        equipDojo  = EquipUtils.GenerateCustomEquip(goodsId)
        equipRefId = checkNumber(equipDojo.equipmentId)
    else
        local hasDojo = isSet(self.params, "dojo")
        if hasDojo then
            equipDojo = self.params.dojo
        else
            if checkNumber(id) > 0 then
                --可能会存在外部不存在id的情况这时就只显示一个空图标
                ---@type EquipmentComponent
                local equipComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.EquipmentComponent)
                equipDojo = equipComponent:GetEquipById(id)
            end
        end
        equipRefId = checkNumber(goodsId)
    end
    
    ---@type GoodsConfMgr
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    ---@type GoodsVo
    local goodsVo = goodsConfMgr:GetGoodsVoById(equipRefId)
    if not isTable(goodsVo) then
        printError(string.format("-------->>>>> 40装备表找不到", equipRefId))
        return
    end
    self.BgClickButton.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(GoodsUtils.GetGoodsBackgroundByQualityType(equipDojo ~= nil and EquipUtils.GetQuality(equipDojo) or goodsVo.quality))
    self.Icon.gameObject:EnsureComponent(typeof(RawImageAlterable)):LoadSprite(goodsVo.photoPath)
    ---@type CardConfMgr
    local cardConfMgr = CardConfMgr:GetInstance()
    ---@type EquipVo
    local equipVo = cardConfMgr:GetEquipVoById(equipRefId)
    if not isTable(equipVo) then
        printError(string.format("-------->>>>> 装备表找不到 %s", equipRefId))
        return
    end

    CfUtils.SetActive(self.EquipCustomized, isCustom == true)

    local isNotNull = isNotNull
    local quality = equipDojo ~= nil and EquipUtils.GetQuality(equipDojo) or equipVo.rare
    local starMax = EquipUtils.GetEquipmentStarMaxByQuality(quality)
    if equipDojo then
        -- 装备等级
        if checkInt(equipDojo.level) == 0 then
            CfUtils.SetActive(self.EquipLevel, false)
        else
            CfUtils.SetActive(self.EquipLevel, true)
            CfUtils.SetUISwitchImage(self.EquipLevelNumber, checkInt(equipDojo.level))
        end
        -- 套装
        CfUtils.FillImage(self.ImgEquipmentSet, EquipUtils.GetEquipmentSetIcon(equipDojo.equipmentId))
        -- 星级
        CfUtils.SetActive(self.EquipStarBg, true)
        CfUtils.SetActive(self.StarGroup, true)
        local childCount = self.StarGroup.transform.childCount
        
        local star = checkInt(equipDojo.star)
        self:RefreshStarGroup(star, true)

        -- local num = 1
        -- for i = 1, childCount do
        --     local img = self.StarGroup:Find("ImgStar" .. i)
        --     if isNotNull(img) then
        --         local isShow = num <= starMax
        --         num = num + 1
        --         KTool.SetActive(img.gameObject, isShow)
        --         if isShow then
        --             CfUtils.SetUISwitchImage(img, (checkInt(equipDojo.star) >= i) and 2 or 1)
        --         end
        --     end
        -- end
        
    else
        CfUtils.SetActive(self.EquipLevel, false)
        --可能会存在外部不存在id的情况这时就只显示一个空图标
        CfUtils.FillImage(self.ImgEquipmentSet, EquipUtils.GetEquipmentSetIcon(self.params.goodsId))
        if self.params.data and checkNumber(self.params.data.isTips) == 1 then
            -- 星级
            CfUtils.SetActive(self.EquipStarBg, true)
            CfUtils.SetActive(self.StarGroup, true)
            -- local childCount = self.StarGroup.transform.childCount
            -- local num = 1
            -- for i = 1, childCount do
            --     local img = self.StarGroup:Find("ImgStar" .. i)
            --     if isNotNull(img) then
            --         local isShow = num <= starMax
            --         num = num + 1
            --         KTool.SetActive(img.gameObject, isShow)
            --         if isShow then
            --             CfUtils.SetUISwitchImage(img, 1)
            --         end
            --     end
            -- end
            self:RefreshStarGroup(0, true)
        else
            
            CfUtils.SetActive(self.EquipStarBg, false)
            CfUtils.SetActive(self.StarGroup, false)
            CfUtils.SetActive(self.ImgNumBg, true)

            CfUtils.SetActive(self.LvOrNoTxt, not string.isEmpty(self.params.text))
            CfUtils.FillText(self.LvOrNoTxt, self.params.text)
        end 
    end
    self:SetRoleGradeAndCareerState(true, goodsId, nil, quality)
end

function GoodNodeMB:RefreshStarGroup(star, isEquip)
    ---@type StarGroup
    local env = CfUtils.GetLuaScr(self.StarGroup, "Game.Behaviours.StarGroup")
    if isNull(env) then
        return
    end
    local CardProgressionConstants  = import("Game.CardProgression.CardProgressionConstants")
    --- 装备解锁红装的只是改变品质 这里要减一
    env:RefreshUI(isEquip and (star >= (EquipUtils.GetLadderRiseParamValue(CardProgressionConstants.LadderRiseParams.StartStar))  and (star - 1) or star) or star)
end

