---__FreshCommonGoodInfo 私有方法
---刷新普通道具的样式
---@param goodsId number 道具id
---@param isShowNo boolean 是否显示普通道具的数量
---@param text string 道具自定义显示的文本
---@param idType number 物品类型
function GoodNodeMB:__FreshCommonGoodInfo(goodsId, isShowNo, text, idType, idAreaType)
    ---@type GoodsConfMgr
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    local vo
    --战斗料理
    --if checkInt(idType) == Constants.IDType.GoodsBattleFood then
    --    local CookingUtils = import('Game.UI.Phone.Cooking.CookingUtils')
    --    vo = CookingUtils.GetBattleCookingFoodVo(goodsId)
    --    vo.photoPath = vo.picture
    --else
        vo = goodsConfMgr:GetGoodsVoById(goodsId, idAreaType)
    --end
    if vo == nil then
        return
    end
    --KTool.SetActive(self.LvBg.gameObject, isShowNo and not string.isEmpty(text))
    if self.ImgNumBg then
        KTool.SetActive(self.ImgNumBg.gameObject, not string.isEmpty(text))
    end
    CfUtils.SetActive(self.LvOrNoTxt, not string.isEmpty(text))

    if checkInt(idType) == Constants.IDType.CharacterCard then
        ---如果是卡牌
        local cardVo = CardConfMgr:GetInstance():GetCardByRefId(goodsId) ---然后取初始的皮肤 然后取头像等
        ---@type CardSkinVo
        local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(cardVo.defaultSkin)
        --- @type UnityEngine.RectTransform
        --self.Icon.gameObject:EnsureComponent(typeof(RawImageAlterable)):LoadSprite(skinVo.buffHead)
        CfUtils.FillImage(self.IconCardHead, skinVo.buffHead)
    elseif idType == Constants.IDType.CardSkin then
        ---@type CardSkinVo
        local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(goodsId)
        --- @type UnityEngine.RectTransform
        --self.Icon.gameObject:EnsureComponent(typeof(RawImageAlterable)):LoadSprite(skinVo.buffHead)
        CfUtils.FillImage(self.IconCardHead, skinVo.buffHead)
    elseif idType == Constants.IDType.RoleCardCustomize then
        ---@TODO
        ---@type RoleCardCustomizeVo
        local cardVo = CardConfMgr:GetInstance():GetCustomizeCardVoById(goodsId)

        CfUtils.FillImage(self.IconCardHead, cardVo.photoPath)
        CfUtils.SetActive(self.Role, true)

    elseif idType == Constants.IDType.PatrolMazeAssist then
        local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
        local assistCardVo = PatrolMazeUtils.GetAssistCardVo(goodsId)
        local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(assistCardVo.skinId)
        CfUtils.FillImage(self.IconCardHead, skinVo.buffHead)

    elseif idType ==Constants.IDType.GoodsHeadOrFrame and (checkNumber(vo.kind) == 1 or checkNumber(vo.kind) == 2 ) then
        if self.CommonPlayerHeadNode then 
            ---@type CommonPlayerHeadNode
            local headEnv  = CfUtils.GetLuaScr(self.CommonPlayerHeadNode, "Game.Behaviours.CommonPlayerHeadNode")
            if headEnv then
                --种类区分：1头像2头像框3徽章4主题
                if checkNumber(vo.kind) == 1 then
                    headEnv:FreshHeadIcon(vo.id, true)
                elseif checkNumber(vo.kind) == 2  then
                    headEnv:FreshFrame(vo.id, true)
                end
            end
        end
    elseif idType == Constants.IDType.GoodsCatBlindBox or idType == Constants.IDType.GoodsCatEggs then
        ---猫球不处理
    else
    --- @type UnityEngine.RectTransform
        self.Icon.gameObject:EnsureComponent(typeof(RawImageAlterable)):LoadSprite(vo.photoPath)
    end

    ----- @type UnityEngine.UI.Text
    --self.LvOrNoTxt.text = checkString(text)
    if idType == Constants.IDType.CharacterCard or idType == Constants.IDType.PatrolMazeAssist then
    elseif idType ==Constants.IDType.GoodsHeadOrFrame then
        ---@type PlayerHeadAvatarVo
        local playerHeadVo = vo
        if playerHeadVo.duration > 0 then
            CfUtils.SetActive(self.countDownBg, true)
            CfUtils.FillText(self.countDownTime, localize('_num_天', {_num_ = playerHeadVo.duration}))
        end
        self.BgClickButton.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(GoodsUtils.GetGoodsBackgroundByQualityType(playerHeadVo.quality))
    else
        --- @type UnityEngine.GameObject
        self.BgClickButton.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(GoodsUtils.GetGoodsBackgroundByQualityType(vo.quality))
    end
    if true == checkBool(isShowNo) and text == nil then
        text = GoodsUtils.GetThingNo(goodsId)
    end
    self.LvOrNoTxt.text = tostring(text)
end

