---SetEquipOrCoreSpecificState
---@param dojo table           EquipCoreVo
---@param cardCareerId number 卡牌职业id
function GoodNodeMB:SetEquipOrCoreSpecificState(dojo, cardCareerId)

    local specificState = false
    if self.goodType == GoodType.EquipCore then
        local equipmentCoreId = dojo.equipmentCoreId
        ---@type EquipCoreVo
        local equipCoreVo = CardConfMgr:GetInstance():GetEquipCoreVoById(equipmentCoreId)
        cardCareerId = checkNumber(cardCareerId)
        local occupationId =  equipCoreVo.occupationId
        specificState = occupationId > 0 and cardCareerId > 0 and occupationId ~= cardCareerId
    end

    local playerCardId = checkNumber(dojo.playerCardId)
    local isEquipped = checkNumber(playerCardId) > 0
    self:RefreshEquippedShowState(isEquipped or specificState)
    KTool.SetActive(self.ImgBgWear.gameObject, isEquipped)
    KTool.SetActive(self.PutTheAsh.gameObject, specificState)

end

---SetRoleGradeAndCareerState
---设置卡的职业信息和元素信息
---@param isShow boolean 是否显示
---@param id number 卡牌id
---@param customQuality? number 自定义品质
function GoodNodeMB:SetRoleGradeAndCareerState(isShow, id, playerDataId, customQuality)
    if not isShow then
        KTool.SetActive(self.Role, false)
        return
    end
    if not id then return end
    local goodsType = GoodsUtils.GetIdType(id)
    local displayType = nil
    if goodsType == Constants.IDType.CharacterCard then
        displayType = Constants.RoleDisplayType.CARD
    elseif goodsType == Constants.IDType.CardSkin then
        displayType = Constants.RoleDisplayType.SKIN
    elseif goodsType == Constants.IDType.RoleCardCustomize then
        displayType = Constants.RoleDisplayType.CustomizeCard
    elseif goodsType == Constants.IDType.PatrolMazeAssist then
        displayType = Constants.RoleDisplayType.MazeAssist
    elseif goodsType == Constants.IDType.Equipment then
        displayType = Constants.RoleDisplayType.Equip
    elseif goodsType == Constants.IDType.GoodsCatBlindBox or goodsType == Constants.IDType.GoodsCatEggs then
        displayType = Constants.RoleDisplayType.CatBall
    else 
        return 
    end
    
    if checkInt(displayType) == Constants.RoleDisplayType.CARD or checkInt(displayType) == Constants.RoleDisplayType.MazeAssist then
        KTool.SetActive(self.Role, true)
        local rare = 0
        local cardId = id
        local cardConf = nil
        if checkInt(displayType) == Constants.RoleDisplayType.MazeAssist then
            local PatrolMazeUtils = import('Game.UI.PatrolMaze.PatrolMazeUtils')
            local assistCardDojo  = PatrolMazeUtils.GetAssistCardDojo(id)
            cardId   = assistCardDojo.cardId
            rare     = assistCardDojo:GetRare()
            cardConf = CardConfMgr:GetInstance():GetCardByRefId(cardId)
        else
            cardConf = CardConfMgr:GetInstance():GetCardByRefId(cardId)
            rare = cardConf.rare
            if checkInt(displayType) == Constants.RoleDisplayType.CARD then
                local playerCardId = checkNumber(playerDataId)
                if playerCardId > 0 then
                    ---@type CardComponent
                    local cardComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.CardComponent)
                    ---@type CardDojo
                    local cardDojo = cardComponent:GetCardById(playerCardId)
                    if cardDojo then
                        rare = cardDojo:GetRare()
                    end
                end
            end
        end
        CfUtils.SetUISwitchImage(self.RareImgIcon, rare + 2)
        CfUtils.SetUISwitchImage(self.ImgIconBg, rare + 2)
        CfUtils.SetActive(self.ImgShelter, true)
        CfUtils.SetUISwitchImage(self.ImgShelter, rare)
        --- @type UnityEngine.GameObject
        self.BgClickButton.gameObject:EnsureComponent(ImageAlterableType):LoadSprite(GoodsUtils.GetGoodsBackgroundByQualityType(rare, false, true))
        CfUtils.FillImage(self.ImgElement, CardUtils.GetCardAttrIconPath(cardConf.attributeType))
        ---@type JobVo
        local jobVo =  CardConfMgr:GetInstance():GetCardCareerRowByType(cardConf.career)
        --print(table.toString(jobVo))
        local jobIcon = jobVo.largeIcon
        CfUtils.FillImage(self.ImgOccupation, jobIcon)
        CfUtils.SetActive(self.Role.transform:Find("Attribute"), true)
    elseif checkInt(displayType) == Constants.RoleDisplayType.CustomizeCard then
        ---@type RoleCardCustomizeVo
        local cardVo = CardConfMgr:GetInstance():GetCustomizeCardVoById(id)
        ------@type GetCardRobotAttributeVo
        local attributeVo = CardConfMgr:GetInstance():GetCardRobotAttributeVo(cardVo.effectId)
        CfUtils.SetUISwitchImage(self.RareImgIcon, attributeVo.cardLevel)
        CfUtils.SetUISwitchImage(self.ImgIconBg, attributeVo.cardLevel)
        CfUtils.SetUISwitchImage(self.ImgShelter, attributeVo.cardLevel)
        CfUtils.SetActive(self.ImgShelter, true)
        CfUtils.FillImage(self.ImgElement, CardUtils.GetCardAttrIconPath(attributeVo.attributeType))
        ---@type JobVo
        local jobVo =  CardConfMgr:GetInstance():GetCardCareerRowByType(attributeVo.career)
        --print(table.toString(jobVo))
        local jobIcon = jobVo.largeIcon
        CfUtils.FillImage(self.ImgOccupation, jobIcon)
        CfUtils.SetActive(self.Role.transform:Find("Attribute"), true)
    elseif checkInt(displayType) == Constants.RoleDisplayType.Equip then
        KTool.SetActive(self.Role, true)
        CfUtils.SetActive(self.Role.transform:Find("Attribute"), false)

        local quality = customQuality
        if customQuality == nil then
            local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
            quality = vo.quality
        end
        CfUtils.SetUISwitchImage(self.RareImgIcon, quality)
        CfUtils.SetUISwitchImage(self.ImgIconBg, quality)
    elseif displayType == Constants.RoleDisplayType.CatBall then
        KTool.SetActive(self.Role, true)
        CfUtils.SetActive(self.Role.transform:Find("Attribute"), false)
        ---@type CatHouseBlindBoxGoodsVo | CatBallGoodsVo
        local vo = GoodsConfMgr:GetInstance():GetGoodsVoById(id)
        if vo then
            local catBallId
            if goodsType == Constants.IDType.GoodsCatBlindBox then
                catBallId = vo.catBallId
            else
                catBallId = vo.cardId
            end
            ---@type CatBallUtils
            local CatBallUtils                = import("Game.CatBall.CatBallUtils")
            local catBallVo = CatBallUtils.GetCatBallVo(catBallId)
            if catBallVo == nil then return end
            local quality = catBallVo.rare + 2 
            CfUtils.SetUISwitchImage(self.RareImgIcon, quality)
            CfUtils.SetUISwitchImage(self.ImgIconBg, quality)
        end
    elseif displayType == Constants.RoleDisplayType.SKIN then
        ---@type GoodsConfMgr
        local goodsConfMgr = GoodsConfMgr:GetInstance()
        local vo = goodsConfMgr:GetGoodsVoById(id)
        CfUtils.SetUISwitchImage(self.ImgShelter, vo.quality - 2)
        CfUtils.SetActive(self.ImgShelter, true)
    end
end

