--是否展示特效
---@param goodsId number 道具id
function GoodNodeMB:ShowEffect(goodsId)
    local goodsConfMgr = GoodsConfMgr:GetInstance()
    local vo = goodsConfMgr:GetGoodsVoById(checkInt(goodsId))
    self:WaitShowEffect(vo)
end
---@param vo GoodsVo
function GoodNodeMB:WaitShowEffect(vo)
    if isTable(vo) then
        if not isNull(self.__qualityEffectGo) then
            ---@type Engine.Lib.PoolManager
            local poolManager = PoolManager.Instance
            poolManager:GiveBack(self.__qualityEffectGo, POOL_MAX)
            self.__qualityEffectGo = nil
        end
        if not isNull(self.__commonEffectGo) then
            ---@type Engine.Lib.PoolManager
            local poolManager = PoolManager.Instance
            poolManager:GiveBack(self.__commonEffectGo, POOL_MAX)
            self.__commonEffectGo = nil
        end
        ---@type Engine.Lib.PoolManager
        local poolManager = PoolManager.Instance
        ---@type UnityEngine.Vector3
        local scale = self.controller.transform.localScale

        local effectParGo = self.Container.transform:Find("UIFX_QualityRoot")
        if effectParGo then 
            effectParGo = effectParGo.gameObject
        else
            return
        end
        if vo.quality == Constants.QualityType.Orange then
            --紫色特效
            self.__qualityEffectGo = poolManager:GetNew(string.format("%s/Ui_common_goods_effect_pinzhikuang_yellow_5.prefab", UIEffectParticlePath), true, 1)
            if not isNull(self.__qualityEffectGo) then
                KTool.SetParent(self.__qualityEffectGo, effectParGo, false)
            end
            --self.__qualityEffectGo.transform:SetScaleXY(scale.x * 1.25, scale.y * 1.25)
        elseif vo.quality == Constants.QualityType.Red then
            ---橙色特效
            self.__qualityEffectGo = poolManager:GetNew(string.format("%s/Ui_common_goods_effect_pinzhikuang_red_6.prefab", UIEffectParticlePath), true, 1)
            --self.__qualityEffectGo.transform:SetScaleXY(scale.x * 1.25, scale.y * 1.25)
            if not isNull(self.__qualityEffectGo) then
                KTool.SetParent(self.__qualityEffectGo, effectParGo, false)
            end
        elseif vo.quality == Constants.QualityType.Colours then
            self.__qualityEffectGo = poolManager:GetNew(string.format("%s/Ui_common_goods_effect_pinzhikuang_colour_7.prefab", UIEffectParticlePath), true, 1)
            if not isNull(self.__qualityEffectGo) then
                KTool.SetParent(self.__qualityEffectGo, effectParGo, false)
            end
        else
            if not isNull(self.__qualityEffectGo) then
                ---@type Engine.Lib.PoolManager
                local poolManager = PoolManager.Instance
                poolManager:GiveBack(self.__qualityEffectGo, POOL_MAX)
                self.__qualityEffectGo = nil
            end
        end
        --统一特效
        self.__commonEffectGo = poolManager:GetNew(string.format("%s/Ui_common_goods_effect_chuxian.prefab", UIEffectParticlePath), true, 1)
        if not isNull(self.__commonEffectGo) then
            KTool.SetParent(self.__commonEffectGo, effectParGo, false)
        end
    end
end

function GoodNodeMB:ShowCommonConvertEffect()
    ---@type Engine.Lib.PoolManager
    local poolManager = PoolManager.Instance
    if not isNull(self.__convertEffectGo) then
        poolManager:GiveBack(self.__convertEffectGo, POOL_MAX)
        self.__convertEffectGo = nil
    end
    self.__convertEffectGo = poolManager:GetNew(string.format("%s/Ui_common_goods_effect_Refresh.prefab", UIEffectParticlePath), true, 1)
    if not isNull(self.__convertEffectGo) then
        KTool.SetParent(self.__convertEffectGo, self.controller.gameObject, false)
    end
