        if isNotNull(self.__commonCanGetEffectGo) then
            KTool.SetActive(self.__commonCanGetEffectGo, isShow)
        end
        return 
    end
    local poolManager = PoolManager.Instance
    if isNull(self.__commonCanGetEffectGo) then
        self.__commonCanGetEffectGo = poolManager:GetNew(string.format("%s/UI_GoodNodeHighlight.prefab", UIEffectParticlePath), true, 1)
