end

-- 增加三星奖励的标签
function GoodNodeMB:SetSanXingFlagShow(isshow)
    KTool.SetActive(self.sanxingbonus, isshow)
end

function GoodNodeMB:SetBonusText(text, status)
    self:SetSanXingFlagShow(true)
    CfUtils.SetUISwitchText(self.BonusText, checkNumber(status))
    self.BonusText.text = checkString(text)
end

-- 增加三星奖励的已获得
function GoodNodeMB:SetSanXingGainShow(isshow)
    KTool.SetActive(self.sanxinggetimg, isshow)
end

--- 绘制上标
---@param type number Constants.RewardSourceType
function GoodNodeMB:FillSuperScript(type)
    local desc, status = self:GetRewardSourceDescAndStatus(type)
    if isNull(desc) or string.isEmpty(desc) then self:SetSanXingFlagShow(false) return end
    self:SetBonusText(desc, status)
end

--- 获取上标的描述和status
---@param type number Constants.RewardSourceType
function GoodNodeMB:GetRewardSourceDescAndStatus(type)
    local desc = ""
    local status = 1

    local sourceType = Constants.RewardSourceType
    if type == sourceType.None then
    elseif type == sourceType.Certain then
        status = 1
    elseif type == sourceType.Probabilistic then
        status = 2
    elseif type == sourceType.FirstPass then
        status = 3
    elseif type == sourceType.ThreeStars then
        status = 4
    elseif type == sourceType.Final then
        status = 4
    elseif type == sourceType.Captain then
        status = 4
    elseif type == sourceType.Sweep then
        status = 4
    end

    desc = GoodsUtils.GetRewardSourceDesc(type)
    return desc, status
end

function GoodNodeMB:OnClickBgAction(eventData)
    if self.cb then
        UICommonUtils.PlayButtonAnimByName(self.Container)
        self.cb(eventData)
    end
end

function GoodNodeMB:SetClickCallback(cb)
    self.cb = cb
    UIEventProxy.Create(self.Container.gameObject).onPointerClick = Bind(self, self.OnClickBgAction)
end

function GoodNodeMB:RefreshEquippedShowState(isShow)
    KTool.SetActive(self.Equipped.gameObject, isShow)
end

function GoodNodeMB:RefreshLockedShowState(isShow)
    KTool.SetActive(self.Locked.gameObject, isShow)
end

function GoodNodeMB:InitPointerDown(cb)
    UIEventProxy.Create(self.Container.gameObject).onPointerDown = cb
end

function GoodNodeMB:InitPointerUp(cb)
    UIEventProxy.Create(self.Container.gameObject).onPointerUp = cb
end

function GoodNodeMB:SetEnoughState(isEnough)
    KTool.SetActive(self.NotEnough.gameObject, checkBool(isEnough))
end

function GoodNodeMB:SetMarkGrayAlpha(isMarkGray , alpha)
    if isNotNull(self.ContainerGrayGraphics) then
        self.ContainerGrayGraphics:MarkGray(isMarkGray)
    end
    if isNotNull(self.ContainerCavnsGroup) and type(alpha) == "number"  then
        self.ContainerCavnsGroup.alpha = alpha
    end
end
---回对象池初始化状态
---按照prefab对象显隐情况重置
function GoodNodeMB:OnReset()

    KTool.SetActive(self.BgClickButton.gameObject, true)
    CfUtils.SetActive(self.IconCardHead, false)
    CfUtils.SetActive(self.Icon, true)
    CfUtils.SetActive(self.PokerCardRoot, false)

    
    if self.CommonPlayerHeadNode then
        KTool.SetActive(self.CommonPlayerHeadNode.gameObject, false)
    end

    if self.EquipAndCore then 
        KTool.SetActive(self.EquipAndCore.gameObject, false)
    end 

    if self.ImgNumBg then
        KTool.SetActive(self.ImgNumBg.gameObject, false)
    end

    if self.CatBall then
        KTool.SetActive(self.CatBall.gameObject, false)
    end

    CfUtils.SetActive(self.LvOrNoTxt, false)
    CfUtils.SetActive(self.GoodStar, false)
    KTool.SetActive(self.CheckImage.gameObject, false)
    KTool.SetActive(self.Container:Find("Imgoccupation"), false) --TODO
    
    KTool.SetActive(self.sanxingbonus, false)

    KTool.SetActive(self.Role, false)
    KTool.SetActive(self.sanxinggetimg, false)
    KTool.SetActive(self.countDownBg, false)
    KTool.SetActive(self.NotEnough.gameObject, false)
    
    -- clear callback
    self:InitPointerDown(nil)
    self:InitPointerUp(nil)
    self:SetClickCallback(nil)
    
    -- 大小
    self.controller.transform.sizeDelta = Vector2(231, 231)
    
    self.controller.transform.pivot = Vector2(0, 1)
    
    ---特效部分
    local poolManager = PoolManager.Instance
    if not isNull(self.__qualityEffectGo) then
        poolManager:GiveBack(self.__qualityEffectGo, POOL_MAX)
        self.__qualityEffectGo = nil
    end
    if not isNull(self.__commonEffectGo) then
        poolManager:GiveBack(self.__commonEffectGo, POOL_MAX)
        self.__commonEffectGo = nil
    end

    if not isNull(self.__convertEffectGo) then
        poolManager:GiveBack(self.__convertEffectGo, POOL_MAX)
        self.__convertEffectGo = nil
    end

    if not isNull(self.__commonCanGetEffectGo) then
        poolManager:GiveBack(self.__commonCanGetEffectGo, POOL_MAX)
        self.__commonCanGetEffectGo = nil
    end

    if not isNull(self.__commonSpecialEffectGo) then
        CfUtils.SetActive(self.__commonSpecialEffectGo, false)
    end
end

function GoodNodeMB:SetIconAlpha(value)
    local imageAlterable = KTool.GetOrAddComponent(self.Icon.gameObject, typeof(RawImageAlterable))
    if imageAlterable then
        imageAlterable:CrossFadeAlpha(value)
    end
end

return GoodNodeMB
